<div id="g-toast"></div>

<script>
const $ = id => document.getElementById(id);
const sleep = ms => new Promise(r => setTimeout(r, ms));

/* ===================== ASSETS (images ibb.co + sons catbox) ===================== */
const A = 'assets/swoge/';
const IMG = {
  'swoge.png':'https://i.ibb.co/P74gycq/swoge.png',
  'volcano.png':'https://i.ibb.co/bgg3xGWr/volcano.png',
  'win-big.png':'https://i.ibb.co/Vcc0Qss9/win-big.png',
  'win-jackpot.png':'https://i.ibb.co/8D9pFsh6/win-jackpot.png',
  'win-mega.png':'https://i.ibb.co/7w5T28L/win-mega.png',
  'win-super.png':'https://i.ibb.co/rfG4NkLz/win-super.png',
  'bg.png':'https://i.ibb.co/hvCW4Wz/bg.png',
  'bonus-text.png':'https://i.ibb.co/B8k5wNw/bonus-text.png',
  'buy-bonus.png':'https://i.ibb.co/1Jf6TVXm/buy-bonus.png',
  'cell-bg.png':'https://i.ibb.co/tTJXJkQF/cell-bg.png',
  'coin-burst.png':'https://i.ibb.co/S4rtkL6q/coin-burst.png',
  'diamond.png':'https://i.ibb.co/RGxwf24s/diamond.png',
  'fire-frame.png':'https://i.ibb.co/PSVRr93/fire-frame.png',
  'fire-halo.png':'https://i.ibb.co/RTxJk3q2/fire-halo.png',
  'goldbar.png':'https://i.ibb.co/21z4XDsx/goldbar.png',
  'grand.png':'https://i.ibb.co/qMkw6Q0P/grand.png',
  'logo.png':'https://i.ibb.co/Kc1GxLzY/logo.png',
  'major.png':'https://i.ibb.co/HfWk2B7G/major.png',
  'mini.png':'https://i.ibb.co/YFk0fr4Y/mini.png',
  'minor.png':'https://i.ibb.co/VYZzgpqc/minor.png',
  'moon.png':'https://i.ibb.co/9HMTwv2Z/moon.png',
  'mult2.png':'https://i.ibb.co/ksYzt5Tg/mult2.png',
  'mult3.png':'https://i.ibb.co/Y7PpbGm3/mult3.png',
  'mult5.png':'https://i.ibb.co/h1Y0rLz2/mult5.png',
  'mystery.png':'data:image/png;base64,',
  'ogcoin.png':'https://i.ibb.co/DfXmG0SV/ogcoin.png',
  'ogjackpot.png':'https://i.ibb.co/d4pRPQNd/ogjackpot.png',
  'plaque-grand.png':'https://i.ibb.co/yc1501VZ/plaque-grand.png',
  'plaque-major.png':'https://i.ibb.co/fLDTssP/plaque-major.png',
  'plaque-mini.png':'https://i.ibb.co/21Z3L5NY/plaque-mini.png',
  'plaque-minor.png':'https://i.ibb.co/3y68S8XB/plaque-minor.png',
  'plaque-og.png':'https://i.ibb.co/GQJ29N7q/plaque-og.png',
  'volcano-meter.png':'https://i.ibb.co/sd0mK3Rq/Chat-GPT-Image-7-ao-t-2026-21-11-53.png',
  'volcano-erupt.png':'https://i.ibb.co/YBzFsMNn/Chat-GPT-Image-7-ao-t-2026-21-09-41.png',
};
const U = f => IMG[f] || (A + f);
const SND = {
  'coin-shower.mp3':'https://files.catbox.moe/0hsxbo.mp3',
  'mystery.mp3':'https://files.catbox.moe/81lvy6.mp3',
  'reel-spin.mp3':'https://files.catbox.moe/izp71f.mp3',
  'anticip.mp3':'https://files.catbox.moe/13vr7r.mp3',
  'near-miss.mp3':'https://files.catbox.moe/1fchwn.mp3',
  'bonus.mp3':'https://files.catbox.moe/ee5827.mp3',
  'life-lost.mp3':'https://files.catbox.moe/o1cbci.mp3',
  'life-gain.mp3':'https://files.catbox.moe/dkfsfi.mp3',
  'bg-music.mp3':'https://files.catbox.moe/vmwcqn.mp3',
  'coin-volcano.mp3':'https://files.catbox.moe/9tsyjy.mp3',   // son quand une piece SWOGE part dans le volcan
  // 'mult-zap.mp3': (pas encore fourni)
};
const S = f => SND[f] || (A + f);

/* ===================== SYMBOLES ===================== */
const SYMBOLS = {
  SWOGE:  { emoji:'🪙', name:'SWOGE Coin',    img:U('swoge.png') },
  DIAMOND:{ emoji:'💎', name:'Diamond Hands', img:U('diamond.png') },
  GOLD:   { emoji:'🥇', name:'Gold Bar',      img:U('goldbar.png') },
  OG:     { emoji:'🐕', name:'OG Coin',       img:U('ogcoin.png') },
  VOLCANO:{ emoji:'🌋', name:'Volcano',       img:U('volcano.png') },
};
const COIN_IMG = {
  value:U('swoge.png'), MINI:U('mini.png'), MINOR:U('minor.png'), MAJOR:U('major.png'), GRAND:U('grand.png'), OG:U('ogjackpot.png'),
  mystery:U('mystery.png'), mult2:U('mult2.png'), mult3:U('mult3.png'), mult5:U('mult5.png'), collect:U('ogcoin.png'), moon:U('moon.png'),
};
function symHTML(key){ const s=SYMBOLS[key]; return s.img ? `<img data-em="${s.emoji}" class="${key==='OG'?'clipc':''}" src="${s.img}" alt="">` : s.emoji; }
const COIN_EM = { value:'🪙', MINI:'🟢', MINOR:'🔵', MAJOR:'🔴', GRAND:'🟠', OG:'🌸', mystery:'❓', mult2:'✖️', mult3:'✖️', mult5:'✖️', collect:'🐕', moon:'🌙' };
document.addEventListener('error', function(e){
  const t=e.target;
  if(t && t.tagName==='IMG' && t.dataset && t.dataset.em && !t.dataset.fell){
    t.dataset.fell='1';
    const span=document.createElement('span');
    span.textContent=t.dataset.em;
    span.style.cssText='display:flex;align-items:center;justify-content:center;width:100%;height:100%;font-size:.82em;line-height:1';
    if(t.parentNode) t.replaceWith(span);
  }
}, true);

/* ===================== MATH (RTP ≈ 70%, calé par simulation — jamais affiché) ===================== */
const SYM_W = { SWOGE:40, DIAMOND:7, GOLD:8, OG:12, VOLCANO:3.5 };   // 3 volcans direct = rare ; le bonus vient surtout du volcan de collecte
const COLLECT_CAP = 300;    // pièces SWOGE à collecter pour faire exploser le volcan
let collectMeter = 0;
const LINE_PAY = { GOLD:8, DIAMOND:12 };
const LINES = [ [0,1,2],[3,4,5],[6,7,8],[0,4,8],[2,4,6] ];
const P_COIN = 0.040, RESPINS = 3, START_CAP = 3;
// ===== MISE : les gains sont proportionnels à la mise (RTP identique, c'est linéaire) =====
const BET_LEVELS = [10,20,50,100,500,1000,10000,100000];
let betIdx = 0, BET = BET_LEVELS[betIdx];
const BONUS_COST_MULT = 33;                  // acheter le bonus = 33 × la mise (doit rester = VOLCANO_BONUS_COST_MULT du serveur)
const dv = n => Math.round(n * BET);         // valeur affichée/créditée = base × mise
function fmtNum(n){ n=Math.round(n); const s=n<0?'-':''; n=Math.abs(n);
  if(n>=1e9) return s+(n/1e9).toFixed(n%1e9?2:0)+'B';
  if(n>=1e6) return s+(n/1e6).toFixed(n%1e6?2:0)+'M';
  if(n>=1e3) return s+(n/1e3).toFixed(n%1e3?1:0)+'K';
  return s+n; }
const JP = { MINI:10, MINOR:50, MAJOR:500, GRAND:1000, OG:5000 };
const COIN_VALUES_W = { 2:38, 4:30, 6:17, 10:9, 16:4, 20:2 };
const COIN_TYPE_W = { VALUE:100, MINI:0.5, MINOR:0.1, MAJOR:0.012, GRAND:0.004, MYSTERY:0.25, MULT:3.2, COLLECT:0.4, MOON:0.6, OGJP:0.0004 };
const MULT_W = { 2:78, 3:20, 5:2 };
function pick(w){ let t=0; for(const k in w) t+=w[k]; let r=Math.random()*t; for(const k in w){ r-=w[k]; if(r<=0) return k; } return Object.keys(w)[0]; }
function newCoin(){
  const t = pick(COIN_TYPE_W);
  if (t==='VALUE') return { type:'VALUE', value:+pick(COIN_VALUES_W) };
  if (t==='MINI')  return { type:'JP', jp:'MINI',  value:JP.MINI };
  if (t==='MINOR') return { type:'JP', jp:'MINOR', value:JP.MINOR };
  if (t==='MAJOR') return { type:'JP', jp:'MAJOR', value:JP.MAJOR };
  if (t==='GRAND') return { type:'JP', jp:'GRAND', value:JP.GRAND };
  if (t==='OGJP')  return { type:'JP', jp:'OG',    value:JP.OG };
  if (t==='MYSTERY'){ const j=pick({MINI:60,MINOR:28,MAJOR:10,GRAND:2}); return { type:'JP', jp:j, value:JP[j], mystery:true }; }
  if (t==='MULT')  return { type:'MULT', mult:+pick(MULT_W) };
  if (t==='COLLECT') return { type:'COLLECT' };
  if (t==='MOON')  return { type:'MOON' };
  return { type:'VALUE', value:10 };
}
function runBonus(startCount){
  startCount = Math.min(startCount, START_CAP);
  const cells = new Array(9).fill(null); let filled=0; const steps=[];
  const init=[]; for(let i=0;i<startCount && filled<9;i++){ cells[i]=newCoin(); init.push({idx:i,coin:cells[i]}); filled++; }
  steps.push({ placed:init, respins:RESPINS, reset:true });
  let respins=RESPINS;
  while (respins>0 && filled<9){
    const placed=[];
    for (let i=0;i<9;i++){ if(cells[i]) continue; if(Math.random()<P_COIN){ cells[i]=newCoin(); placed.push({idx:i,coin:cells[i]}); filled++; if(filled>=9) break; } }
    const reset = placed.length>0; if (reset) respins=RESPINS; else respins--;
    steps.push({ placed, respins, reset });
  }
  const moons = cells.filter(c=>c&&c.type==='MOON').length; const mp=[];
  for (let m=0;m<moons;m++){ const add=1+Math.floor(Math.random()*3); for(let a=0;a<add;a++){ const idx=cells.indexOf(null); if(idx<0) break; cells[idx]=newCoin(); mp.push({idx,coin:cells[idx]}); filled++; } }
  if (mp.length) steps.push({ placed:mp, respins:0, reset:false, moon:true });
  let valueSum=0, jpSum=0, multTotal=1, collectors=0;
  for (const c of cells){ if(!c) continue;
    if (c.type==='VALUE') valueSum+=c.value; else if (c.type==='JP') jpSum+=c.value;
    else if (c.type==='MULT') multTotal*=c.mult; else if (c.type==='COLLECT') collectors++; }
  let total = valueSum; if (collectors>0) total += valueSum*collectors; total *= multTotal; total += jpSum;
  return { cells, steps, total: Math.round(total), filled };
}
function computeSpin(){
  const grid = new Array(9); for(let i=0;i<9;i++) grid[i]=pick(SYM_W);
  const lineWins=[]; let baseWin=0;
  for (const L of LINES){ const a=grid[L[0]]; if(a===grid[L[1]]&&a===grid[L[2]] && LINE_PAY[a]){ lineWins.push({line:L, sym:a, amount:LINE_PAY[a]}); baseWin+=LINE_PAY[a]; } }
  const volc = grid.filter(s=>s==='VOLCANO').length;
  const bonus = volc>=3 ? runBonus(volc) : null;
  return { grid, lineWins, baseWin, bonus };
}

/* ===================== SON ===================== */
let AC=null; function ac(){ if(!AC){ try{ AC=new (window.AudioContext||window.webkitAudioContext)(); }catch(e){} } if(AC&&AC.state==='suspended') AC.resume(); return AC; }
function tone(f,d,type='sine',v=.1,sl){ const c=ac(); if(!c) return; const o=c.createOscillator(),g=c.createGain(); o.type=type; o.frequency.setValueAtTime(f,c.currentTime); if(sl)o.frequency.exponentialRampToValueAtTime(sl,c.currentTime+d); o.connect(g);g.connect(c.destination); g.gain.setValueAtTime(v,c.currentTime); g.gain.exponentialRampToValueAtTime(.001,c.currentTime+d); o.start();o.stop(c.currentTime+d); }
const sndWin=()=>tone(660,.1,'triangle',.1,990), sndCoin=()=>tone(720,.08,'triangle',.09,1100),
      sndJP=()=>{tone(500,.15,'square',.14,900);setTimeout(()=>tone(900,.2,'square',.14,1400),120);}, sndBonus=()=>{tone(200,.4,'sawtooth',.16,600);setTimeout(()=>tone(400,.3,'square',.14,800),200);};
function bonusFlash(){ const d=document.createElement('div'); d.className='bonus-flash'; $('machine').appendChild(d); setTimeout(()=>d.remove(),700); }
function winLevel(total, hadBigJp){
  if (hadBigJp || total>=1500) return 'jackpot';
  if (total>=600) return 'mega';
  if (total>=200) return 'super';
  if (total>=60)  return 'big';
  return null;
}
/* ===== Musique de fond (boucle) ===== */
let bgm=null, bgmOn=true;
function startBgm(){
  try{
    if(!bgm){ bgm=new Audio(S('bg-music.mp3')); bgm.loop=true; bgm.volume=0.35; }
    if(bgmOn) bgm.play().catch(()=>{});
  }catch(e){}
}
function toggleBgm(){ bgmOn=!bgmOn; if(!bgm) startBgm(); else if(bgmOn) bgm.play().catch(()=>{}); else bgm.pause(); return bgmOn; }
/* l'autoplay audio est bloque tant que l'utilisateur n'a pas interagi : on demarre au 1er tap */
['pointerdown','click','touchstart','keydown'].forEach(ev=>
  document.addEventListener(ev, function once(){ startBgm(); ['pointerdown','click','touchstart','keydown'].forEach(e=>document.removeEventListener(e, once)); }, {once:false}));
let coinVolSnd=null;
function playCoinVolcanoMp3(){ try{ if(!coinVolSnd){ coinVolSnd=new Audio(S('coin-volcano.mp3')); coinVolSnd.volume=0.7; } const s=coinVolSnd.cloneNode(); s.volume=0.7; s.playbackRate=1.6; s.play().catch(()=>{}); }catch(e){} }
let showerSnd=null;
function playShowerMp3(){ try{ if(!showerSnd){ showerSnd=new Audio(S('coin-shower.mp3')); showerSnd.volume=0.8; } showerSnd.currentTime=0; showerSnd.play().catch(()=>{}); }catch(e){} }
let mystSnd=null;
function playMysteryMp3(){ try{ if(!mystSnd){ mystSnd=new Audio(S('mystery.mp3')); mystSnd.volume=0.85; } mystSnd.currentTime=0; mystSnd.play().catch(()=>{}); }catch(e){} }
let zapSnd=null;
function playZapMp3(){ try{ if(!zapSnd){ zapSnd=new Audio(S('mult-zap.mp3')); zapSnd.volume=0.8; } zapSnd.currentTime=0; zapSnd.play().catch(()=>{}); }catch(e){} }
function showCoinBurst(){ const c=$('coin-burst'); c.classList.remove('show'); void c.offsetWidth; c.classList.add('show'); playShowerMp3(); setTimeout(()=>c.classList.remove('show'), 1950); }
function showWinBanner(level){
  const b=$('win-banner'); b.style.backgroundImage=`url('${U('win-'+level+'.png')}')`;
  b.classList.remove('show'); void b.offsetWidth; b.classList.add('show');
  showCoinBurst();
  setTimeout(()=>b.classList.remove('show'), 2450);
}
function showBonusBanner(){
  const b=$('bonus-banner'), g=$('bonus-glow');
  g.classList.remove('show'); b.classList.remove('show'); void b.offsetWidth;
  g.classList.add('show'); b.classList.add('show'); showCoinBurst();
  setTimeout(()=>{ b.classList.remove('show'); g.classList.remove('show'); }, 2750);
}

/* ===================== LADDER ===================== */
const LADDER=[['OG',JP.OG,'og'],['GRAND',JP.GRAND,'grand'],['MAJOR',JP.MAJOR,'major'],['MINOR',JP.MINOR,'minor'],['MINI',JP.MINI,'mini']];
$('ladder').innerHTML = LADDER.map(([k,v,img])=>`<div class="jp-plaque" data-jp="${k}" style="background-image:url('${U('plaque-'+img+'.png')}')"><span></span></div>`).join('');
const LADDER_ALL={100:'data:image/png;base64,',200:'data:image/png;base64,',500:'data:image/png;base64,',1000:'data:image/png;base64,',2500:'data:image/png;base64,',5000:'data:image/png;base64,',10000:'data:image/png;base64,',20000:'data:image/png;base64,',25000:'data:image/png;base64,',50000:'data:image/png;base64,',100000:'data:image/png;base64,',250000:'data:image/png;base64,',500000:'data:image/png;base64,',1000000:'data:image/png;base64,',2500000:'data:image/png;base64,',5000000:'data:image/png;base64,',10000000:'data:image/png;base64,',50000000:'data:image/png;base64,',100000000:'data:image/png;base64,',500000000:'data:image/png;base64,'};
function renderLadderValues(){ LADDER.forEach(([k,v])=>{ const p=document.querySelector('.jp-plaque[data-jp="'+k+'"]'); if(!p)return; const el=p.querySelector('span'); const val=dv(v); const img=LADDER_ALL[val]; if(img){ p.style.backgroundImage="url('"+img+"')"; if(el) el.textContent=''; } else { if(el) el.textContent=fmtNum(val)+'⭐'; } }); }
function flashLadder(jp){ const el=document.querySelector(`.jp-plaque[data-jp="${jp}"]`); if(el){ el.classList.add('hot'); setTimeout(()=>el.classList.remove('hot'),1600); } }

/* ===================== GRILLE ===================== */
$('grid').innerHTML = Array.from({length:9},()=>'<div class="cell"></div>').join('');
const cells = [...document.querySelectorAll('#grid .cell')];
function renderGrid(g){ g.forEach((s,i)=>{ cells[i].innerHTML = symHTML(s); cells[i].classList.remove('win'); }); }
renderGrid(Array.from({length:9},()=>pick(SYM_W)));
function clearCells(){ cells.forEach(c=>{ c.innerHTML=''; c.classList.remove('win','trigger','has-coin'); }); }

/* ===================== ANIMATION SPIN (base) ===================== */
const TEASE_W = { MINI:50, MINOR:26, MAJOR:14, GRAND:8, OG:2 };
const TEASE_CHANCE = 0.045;
function teaserOr(i, outcome, winSet){
  if (!outcome.bonus && !winSet.has(i) && outcome.grid[i]!=='VOLCANO' && (outcome.grid[i]==='SWOGE'||outcome.grid[i]==='OG') && Math.random()<TEASE_CHANCE){
    const jp=pick(TEASE_W); return `<div class="land teaser"><img data-em="${COIN_EM[jp]}" src="${COIN_IMG[jp]}"><span class="cv">${fmtNum(dv(JP[jp]))}</span></div>`;
  }
  return `<div class="land">${symHTML(outcome.grid[i])}</div>`;
}
const vcol = (g,c) => (g[c]==='VOLCANO'?1:0)+(g[3+c]==='VOLCANO'?1:0)+(g[6+c]==='VOLCANO'?1:0);
/* Toutes les cases n'ont pas besoin d'être remplies : on laisse des cases vides
   (uniquement des SWOGE non gagnants, jamais un volcan ni une ligne gagnante) →
   plus léger + rendu plus proche d'une vraie machine. */
let lastBlanks=new Set();   // cases laissées vides au dernier spin (pour ne pas y faire voler de pièce)
function blankSet(grid, winSet){
  const blanks=new Set();
  for(let i=0;i<9;i++){
    if(winSet.has(i) || grid[i]==='VOLCANO') continue;   // jamais un volcan ni une ligne gagnante
    if(Math.random()<0.32) blanks.add(i);                 // les 9 cases ne sont pas toutes remplies (3→9 pièces)
  }
  return blanks;
}
async function animateSpin(outcome){
  cells.forEach(c=>{ c.classList.remove('win','trigger'); c.innerHTML=''; });
  const winSet=new Set(); outcome.lineWins.forEach(w=>w.line.forEach(i=>winSet.add(i)));
  // On décide TÔT quelles cases restent vides → le rouleau s'arrête directement sur du vide
  // (avant : le symbole apparaissait puis disparaissait). Jamais un volcan ni une ligne gagnante.
  const blanks = outcome.bonus ? new Set() : blankSet(outcome.grid, winSet);
  lastBlanks = blanks;
  const grid=$('grid'), gr=grid.getBoundingClientRect();
  const K=14, overlays=[];
  for(let c=0;c<3;c++){
    const top=cells[c].getBoundingClientRect();
    const step=cells[3+c].getBoundingClientRect().top - top.top;
    const cellH=top.height, gap=step-cellH;
    const ov=document.createElement('div'); ov.className='reel-ov';
    ov.style.left=(top.left-gr.left)+'px'; ov.style.top=(top.top-gr.top)+'px';
    ov.style.width=top.width+'px'; ov.style.height=(3*cellH+2*gap)+'px';
    const strip=document.createElement('div'); strip.className='reel-strip';
    let html='';
    for(let k=0;k<K;k++) html+=`<div class="reel-cell" style="height:${cellH}px;margin-bottom:${gap}px">${Math.random()<0.20?'':symHTML(pick(SYM_W))}</div>`;
    for(let r=0;r<3;r++){ const gi=r*3+c; html+=`<div class="reel-cell" style="height:${cellH}px;margin-bottom:${gap}px">${blanks.has(gi)?'':symHTML(outcome.grid[gi])}</div>`; }
    strip.innerHTML=html; ov.appendChild(strip); grid.appendChild(ov);
    overlays.push({ov,strip,step});
  }
  const anticip = (vcol(outcome.grid,0)+vcol(outcome.grid,1))>=2;
  await zzz(20);
  const base=800*TF, stagger=320*TF, ANTICIP=1700*TF;
  const durs=[base, base+stagger, anticip ? base+stagger+ANTICIP : base+2*stagger];
  overlays.forEach((o,idx)=>{ o.strip.style.transition=`transform ${durs[idx]}ms cubic-bezier(.1,.55,.15,1)`;
    o.strip.classList.add('mblur');
    setTimeout(()=>o.strip.classList.remove('mblur'), Math.max(200, durs[idx]-340));
    requestAnimationFrame(()=>{ o.strip.style.transform=`translateY(${-(K*o.step)}px)`; }); });
  reelSpinStart();
  if (anticip){ setTimeout(()=>{ overlays[2].ov.classList.add('anticip'); playAnticipMp3(); }, base+stagger+120); }
  await zzz(durs[2] + 170);
  reelSpinStop(); stopAnticipMp3(); overlays[2].ov.classList.remove('anticip');
  for(let i=0;i<9;i++) cells[i].innerHTML = blanks.has(i) ? '' : teaserOr(i, outcome, winSet);
  overlays.forEach(o=>o.ov.remove());

  const vIdx=[]; outcome.grid.forEach((s,i)=>{ if(s==='VOLCANO') vIdx.push(i); });
  if (outcome.bonus){
    vIdx.forEach(i=>cells[i].classList.add('trigger'));
    bonusFlash(); sndJP(); setTimeout(sndWin,160); setTimeout(sndBonus,320); showBonusBanner();
    await zzz(2650);
    cells.forEach(c=>c.classList.remove('trigger'));
  } else if (vIdx.length>=1){
    vIdx.forEach(i=>cells[i].classList.add('trigger'));
    playNearMp3();
    await zzz(vIdx.length>=2 ? 950 : 700);
    cells.forEach(c=>c.classList.remove('trigger'));
  }
  if (outcome.lineWins.length){
    winSet.forEach(i=>cells[i].classList.add('win'));
    $('last-win').textContent = fmtNum(dv(outcome.baseWin)); sndWin(); await zzz(700);
    cells.forEach(c=>c.classList.remove('win'));
  }
}

/* ===================== ANIMATION BONUS (dans la grille principale) ===================== */
/* halo de feu UNIQUEMENT sur les pièces spéciales (x2/x3/x5, minor/major/grand/og, mystère…) — pas sur les pièces valeur */
function coinWrap(inner, halo){ return `<div class="coin imgcoin">${halo?'<div class="fire-halo"></div>':''}${inner}</div>`; }
function coinHTML(coin){
  if (coin.type==='VALUE') return coinWrap(`<img data-em="${COIN_EM.value}" src="${COIN_IMG.value}"><span class="cv">${fmtNum(dv(coin.value))}</span>`, false);
  if (coin.type==='JP'){
    if (coin.mystery) return coinWrap(`<img data-em="${COIN_EM.mystery}" src="${COIN_IMG.mystery}">`, true);
    return coinWrap(`<img data-em="${COIN_EM[coin.jp]}" src="${COIN_IMG[coin.jp]}">`, true);   // l'image porte déjà le nom
  }
  if (coin.type==='MULT') return coinWrap(`<img data-em="${COIN_EM['mult'+coin.mult]}" src="${COIN_IMG['mult'+coin.mult]}">`, true);
  if (coin.type==='COLLECT') return coinWrap(`<img data-em="${COIN_EM.collect}" class="clipc" src="${COIN_IMG.collect}">`, true);
  if (coin.type==='MOON') return coinWrap(`<img data-em="${COIN_EM.moon}" class="clipc" src="${COIN_IMG.moon}">`, true);
  return '';
}
/* pièce ALLÉGÉE pour le défilé du bonus (pas de fire-halo ni double ombre) → beaucoup plus fluide */
function coinReel(coin){
  let img='', cv='';
  if(coin.type==='VALUE'){ img=COIN_IMG.value; cv=`<span class="cv">${fmtNum(dv(coin.value))}</span>`; }
  else if(coin.type==='JP'){ img=coin.mystery?COIN_IMG.mystery:COIN_IMG[coin.jp]; }
  else if(coin.type==='MULT'){ img=COIN_IMG['mult'+coin.mult]; }
  else if(coin.type==='COLLECT'){ img=COIN_IMG.collect; }
  else if(coin.type==='MOON'){ img=COIN_IMG.moon; }
  else return '';
  return `<div class="coinlite"><img data-em="${COIN_EM.value}" src="${img}" alt="">${cv}</div>`;
}
const lives = n => { n=Math.max(0,Math.min(RESPINS,n)); return '❤️'.repeat(n)+'🖤'.repeat(RESPINS-n); };
let reelSnd=null;
function reelSpinStart(){ try{ if(!reelSnd){ reelSnd=new Audio(S('reel-spin.mp3')); reelSnd.loop=true; reelSnd.volume=0.5; } reelSnd.currentTime=0; reelSnd.play().catch(()=>{}); }catch(e){} }
function reelSpinStop(){ try{ if(reelSnd){ reelSnd.pause(); reelSnd.currentTime=0; } }catch(e){} }
let antSnd=null;
function playAnticipMp3(){ try{ if(!antSnd){ antSnd=new Audio(S('anticip.mp3')); antSnd.volume=0.75; } antSnd.currentTime=0; antSnd.play().catch(()=>{}); }catch(e){} }
function stopAnticipMp3(){ try{ if(antSnd){ antSnd.pause(); antSnd.currentTime=0; } }catch(e){} }
let nearSnd=null;
function playNearMp3(){ try{ if(!nearSnd){ nearSnd=new Audio(S('near-miss.mp3')); nearSnd.volume=0.85; } nearSnd.currentTime=0; nearSnd.play().catch(()=>{}); }catch(e){} }
let bonusSnd=null, lifeSnd=null, gainSnd=null;
function playBonusMp3(){ try{ if(!bonusSnd){ bonusSnd=new Audio(S('bonus.mp3')); bonusSnd.volume=0.75; } bonusSnd.currentTime=0; bonusSnd.play().catch(()=>{}); }catch(e){} }
function playLifeMp3(){ try{ if(!lifeSnd){ lifeSnd=new Audio(S('life-lost.mp3')); lifeSnd.volume=0.8; } lifeSnd.currentTime=0; lifeSnd.play().catch(()=>{}); }catch(e){} }
function playGainMp3(){ try{ if(!gainSnd){ gainSnd=new Audio(S('life-gain.mp3')); gainSnd.volume=0.8; } gainSnd.currentTime=0; gainSnd.play().catch(()=>{}); }catch(e){} }

/* ===================== BIG WIN (SIZZLING) ===================== */
function coinRain(n){
  const box=$('bigwin-rain'); if(!box) return;
  for(let i=0;i<n;i++){
    const c=document.createElement('img'); c.className='rain-coin'; c.src=U('swoge.png'); c.dataset.em='🪙';
    const sz=(4.5+Math.random()*5.5);
    c.style.left=(Math.random()*94)+'%'; c.style.width=sz+'vh'; c.style.height=sz+'vh';
    const dur=(1.5+Math.random()*1.7);
    c.style.animation='rainFall '+dur+'s linear '+(Math.random()*0.9).toFixed(2)+'s forwards';
    box.appendChild(c);
    setTimeout(()=>c.remove(), (dur+1.1)*1000);
  }
}
async function bigWin(amount, label){
  const ov=$('bigwin'), amt=$('bigwin-amt'), tt=$('bigwin-title'); if(!ov) return;
  if(tt&&label) tt.textContent=label;
  setSpriteState('bonus', 6000);
  ov.classList.add('show');
  coinRain(30); try{ playShowerMp3(); }catch(e){}
  const start=Date.now(), dur=3600*TF; if(amt) amt.textContent='0';   // montée plus lente (on savoure le gain)
  await new Promise(res=>{ (function up(){ const k=Math.min(1,(Date.now()-start)/dur);
    if(amt) amt.textContent=fmtNum(Math.floor(amount*k)); if(k<1) requestAnimationFrame(up); else res(); })(); });
  if(amt) amt.textContent=fmtNum(amount);
  try{ sndJP(); }catch(e){} coinRain(20);
  await zzz(3000);   // on laisse le résultat affiché plus longtemps (le temps que la musique finisse)
  ov.classList.remove('show');
}
/* Rouleaux du BONUS : les cases vides tournent (on voit les pièces défiler dans les colonnes)
   puis se posent sur les nouvelles pièces (ou rien) — la partie la plus soignée du jeu. */
/* pièce aléatoire pour le défilé (on voit passer les MINI/MINOR/MAJOR, x2/x3, mystery) */
function randBonusCoin(){
  const r=Math.random();
  if(r<0.42) return {type:'VALUE', value:[2,4,6,10,16,20][(Math.random()*6)|0]};
  if(r<0.62) return {type:'MULT', mult:[2,3,5][(Math.random()*3)|0]};
  if(r<0.72) return {type:'JP', mystery:true, jp:'MINOR'};
  return {type:'JP', jp:['MINI','MINOR','MAJOR','GRAND'][(Math.random()*4)|0]};
}
async function bonusReelSpin(step){
  const grid=$('grid'), gr=grid.getBoundingClientRect();
  const placedMap={}; (step.placed||[]).forEach(p=>placedMap[p.idx]=p.coin);
  const empties=[]; for(let i=0;i<9;i++){ if(!cells[i].classList.contains('has-coin')) empties.push(i); }
  if(!empties.length) return;
  reelSpinStart();
  const K=11, ovs=[];
  empties.forEach(i=>{
    const cr=cells[i].getBoundingClientRect(), cellH=cr.height;
    const ov=document.createElement('div'); ov.className='reel-ov';
    ov.style.left=(cr.left-gr.left)+'px'; ov.style.top=(cr.top-gr.top)+'px'; ov.style.width=cr.width+'px'; ov.style.height=cellH+'px';
    const strip=document.createElement('div'); strip.className='reel-strip mblur';
    // pièces allégées (coinReel) pendant le défilé → fluide ; la vraie pièce finale (avec halo si spéciale) est posée à l'arrêt
    let html=''; for(let k=0;k<K;k++) html+=`<div class="reel-cell" style="height:${cellH}px">${coinReel(randBonusCoin())}</div>`;
    html+=`<div class="reel-cell" style="height:${cellH}px">${placedMap[i]?coinReel(placedMap[i]):''}</div>`;
    strip.innerHTML=html; ov.appendChild(strip); grid.appendChild(ov);
    ovs.push({ov,strip,i,cellH});
  });
  let maxDur=0;
  ovs.forEach(o=>{
    const col=o.i%3, coin=placedMap[o.i];
    const big = coin && (coin.mystery || coin.type==='JP');   // MAJOR/GRAND/OG/mystery = gros lot
    let dur=(1500+col*520)*TF;                                 // encore plus lent : on voit les pièces défiler
    if(big) dur += 1400*TF;                                    // un gros lot ralentit encore plus (on y croit)
    maxDur=Math.max(maxDur,dur);
    o.strip.style.transition=`transform ${dur}ms cubic-bezier(.08,.72,.06,1)`;   // forte décélération = on lit les symboles à l'arrivée
    setTimeout(()=>o.strip.classList.remove('mblur'), Math.max(260,dur-800));    // net plus tôt → on voit passer les symboles
    if(big){ setTimeout(()=>{ o.ov.classList.add('anticip'); playAnticipMp3(); }, Math.max(500,dur-1250)); }  // anticipation dorée
    requestAnimationFrame(()=>{ o.strip.style.transform=`translateY(${-(K*o.cellH)}px)`; });
  });
  await sleep(maxDur+320);
  reelSpinStop(); stopAnticipMp3();
  ovs.forEach(o=>o.ov.classList.remove('anticip'));
  const placed=step.placed||[];
  placed.forEach(p=>{
    cells[p.idx].innerHTML=coinHTML(p.coin); cells[p.idx].classList.add('has-coin','drop');
    setTimeout(()=>cells[p.idx].classList.remove('drop'),430);
    if(p.coin.mystery){ /* révélé juste après (roulette) */ }
    else if(p.coin.type==='MULT'){ playZapMp3(); cells[p.idx].classList.add('zap'); setTimeout(()=>cells[p.idx].classList.remove('zap'),520); }
    else if(p.coin.type==='JP'){ sndJP(); flashLadder(p.coin.jp); }
    else sndCoin();
  });
  ovs.forEach(o=>o.ov.remove());
  // Révélation "roulette" des pièces MYSTÈRE : les symboles défilent puis s'arrêtent sur la vraie valeur
  for(const p of placed){ if(p.coin.mystery) await revealMystery(p.idx, p.coin); }
}
/* Roulette de révélation d'une pièce mystère : on fait défiler des faces (x2/x3, valeurs, minor/major…)
   puis on s'arrête sur la vraie pièce cachée. */
async function revealMystery(idx, coin){
  const cell=cells[idx]; if(!cell) return;
  playMysteryMp3();
  const faces=['value','value','mult2','mult3','MINI','MINOR','MAJOR','GRAND'];
  const t0=Date.now(), dur=1050*TF;
  while(Date.now()-t0<dur){
    const f=faces[(Math.random()*faces.length)|0];
    const src=COIN_IMG[f]||COIN_IMG.value;
    cell.innerHTML=coinWrap(`<img src="${src}">`, true);
    await sleep(Math.max(45, 80*TF));
  }
  // arrêt sur la vraie valeur cachée (le jackpot que le mystère portait)
  const real = coin.type==='JP' ? {type:'JP', jp:coin.jp, value:coin.value} : coin;
  cell.innerHTML=coinHTML(real); cell.classList.add('drop');
  setTimeout(()=>cell.classList.remove('drop'),430);
  flashLadder(coin.jp); sndJP();
  await sleep(260*TF);
}
async function animateBonus(bonus){
  playBonusMp3();
  sndBonus();
  setSpriteState('bonus', 120000);   // SWOGE reste en mode bonus pendant tout le bonus
  clearCells(); $('machine').classList.add('bonus'); $('btotal').textContent=''; $('respins').textContent=lives(RESPINS);
  await zzz(800);
  for (let si=0; si<bonus.steps.length; si++){
    const step = bonus.steps[si];
    await bonusReelSpin(step);                     // les rouleaux tournent, les pièces tombent
    $('respins').textContent = lives(step.respins);
    if (!step.reset && !step.moon){
      // VIE PERDUE : bien visible (secousse + flash rouge + pause plus longue)
      playLifeMp3();
      const rb=$('respins-box'), sc=$('scene');
      if(rb){ rb.classList.remove('lost'); void rb.offsetWidth; rb.classList.add('lost'); rb.style.color='#ff5b5b'; }
      if(sc){ sc.classList.remove('shake'); void sc.offsetWidth; sc.classList.add('shake'); }
      await zzz(800);
      if(rb){ rb.classList.remove('lost'); rb.style.color=''; } if(sc) sc.classList.remove('shake');
    } else {
      if (step.reset && si>0 && step.placed.length){ playGainMp3(); $('respins-box').style.color='#5be86a'; await zzz(450); $('respins-box').style.color=''; }
      else await zzz(350);
    }
  }
  const target=dv(bonus.total), start=Date.now(), dur=2600*TF;   // montée plus lente du compteur d'étoiles
  await new Promise(res=>{ (function up(){ const k=Math.min(1,(Date.now()-start)/dur); $('btotal').textContent=`+${fmtNum(target*k)} ⭐`; if(k<1) requestAnimationFrame(up); else res(); })(); });
  $('last-win').textContent = fmtNum(target); sndJP();
  const hadBigJp = bonus.cells.some(c => c && c.type==='JP' && (c.jp==='GRAND' || c.jp==='OG'));
  const lvl = winLevel(bonus.total, hadBigJp);   // seuils sur la valeur de BASE (indépendante de la mise)
  if (lvl==='jackpot' || lvl==='mega'){
    await bigWin(target, lvl==='jackpot' ? '💥 MEGA SIZZLING 💥' : '🔥 SIZZLING 🔥');   // gros gain = plein écran
  } else if (lvl){ showWinBanner(lvl); sndBonus(); await zzz(2500); }
  else { await zzz(1300); }
  $('machine').classList.remove('bonus'); clearCells();
  setSpriteState('idle');   // retour au repos à la fin du bonus
  renderGrid(Array.from({length:9},()=>pick(SYM_W)));
}

/* ===================== VOLCAN DE COLLECTE ===================== */
function setMeterUI(){ /* pas d'indicateur : le bonus est une surprise (le compteur reste interne) */ }
/* ===== SWOGE collecteur animé (sprite sheets 8x8 = 64 frames) ===== */
const SPRITE = {
  idle:  'https://files.catbox.moe/45jrr8.png',   // au repos (pas de pièce)
  coins: 'https://files.catbox.moe/3nnjae.png',   // des pièces rentrent dedans
  bonus: 'https://files.catbox.moe/e1fv2m.png'    // bonus activé
};
(function preloadSprites(){ for(const k in SPRITE){ const im=new Image(); im.src=SPRITE[k]; } })();
let spriteState='idle', spriteFrame=0, spriteLock=0;
function setSpriteState(name, lockMs){
  const el=$('vmeter-sprite'); if(!el||!SPRITE[name]) return;
  if(name!=='idle'){ spriteLock = Date.now() + (lockMs||1200); }   // reste dans cet état un moment
  else { spriteLock = 0; }
  if(name===spriteState) return;
  spriteState=name; el.style.backgroundImage="url('"+SPRITE[name]+"')";
}
/* place le SWOGE au-dessus de la grille (premier plan), aligné dynamiquement */
function positionSwoge(){
  const vm=$('vmeter'), m=$('machine'); if(!vm||!m) return;
  const r=m.getBoundingClientRect(); if(!r.width) return;
  const desktop = window.innerWidth>820 && window.innerWidth>window.innerHeight;
  const wf = desktop ? 0.5 : 0.62;            // perso un peu plus compact sur PC
  const of = desktop ? 0.58 : 0.80;           // et moins haut (tête sous l'échelle)
  const w=r.width*wf;
  vm.style.width=w+'px'; vm.style.height=w+'px';
  vm.style.left=(r.left + r.width/2 - w/2)+'px';
  vm.style.top=(r.top - w*of)+'px';
  // VIES du bonus : en BAS du rectangle de jeu, par-dessus la grille (premier plan)
  const lv=$('respins-box');
  if(lv){ lv.style.left=(r.left + r.width/2)+'px';
    lv.style.top=(r.bottom - (lv.offsetHeight||34) - 6)+'px'; }
}
window.addEventListener('resize', positionSwoge);
window.addEventListener('scroll', positionSwoge, true);
[80,300,700,1400,2500].forEach(function(t){ setTimeout(positionSwoge,t); });
function tickSprite(){
  const el=$('vmeter-sprite'); if(!el) return;
  if(spriteState!=='idle' && Date.now()>=spriteLock){ spriteState='idle'; el.style.backgroundImage="url('"+SPRITE.idle+"')"; }
  spriteFrame=(spriteFrame+1)%64;
  const col=spriteFrame%8, row=(spriteFrame/8)|0;
  el.style.backgroundPositionX=(col/7*100)+'%';
  el.style.backgroundPositionY=(row/7*100)+'%';
  if((spriteFrame % 12)===0) positionSwoge();   // ré-aligne périodiquement (résiste aux changements de layout)
}
setInterval(tickSprite, 42);   // ~24 images/s
function flyCoin(fromEl, delay){
  const vm=$('vmeter'); if(!vm||!fromEl) return;
  const ref=fromEl.querySelector('img') || fromEl;   // position de départ = la case SWOGE
  const fr=ref.getBoundingClientRect(), vr=vm.getBoundingClientRect();
  if(!fr.width||!vr.width) return;
  const sx=fr.left+fr.width/2, sy=fr.top+fr.height/2;
  const ex=vr.left+vr.width*0.5, ey=vr.top+vr.height*0.52;
  const c=document.createElement('img'); c.className='fly-coin'; c.src=U('swoge.png');   // TOUJOURS la pièce SWOGE (jamais un teaser jackpot)
  c.style.width=fr.width+'px'; c.style.height=fr.height+'px'; c.style.left=(sx-fr.width/2)+'px'; c.style.top=(sy-fr.height/2)+'px';
  document.body.appendChild(c);
  requestAnimationFrame(()=>{ var fd=(.55*TF); c.style.transition='transform '+fd+'s cubic-bezier(.55,.06,.3,1), opacity '+fd+'s ease-in';
    c.style.transitionDelay=(delay*TF)+'ms';
    c.style.transform=`translate(${ex-sx}px, ${ey-sy}px) scale(.14) rotate(720deg)`; c.style.opacity='.15'; });
  setTimeout(()=>{ try{playCoinVolcanoMp3();}catch(e){} }, Math.max(0, delay*TF));   // son au DÉPART de la pièce (synchro, plus réactif)
  setTimeout(()=>{ try{sndCoin();}catch(e){} c.remove(); }, (delay+590)*TF);          // petit "clink" à l'arrivée
}
async function collectSwoge(grid){
  const idx=[]; grid.forEach((sy,i)=>{ if(sy==='SWOGE' && !lastBlanks.has(i)) idx.push(i); });   // seulement les SWOGE réellement affichés (pas les cases vides)
  if(!idx.length){ return; }
  setSpriteState('coins', idx.length*95*TF + 900);   // SWOGE réagit quand les pièces rentrent
  idx.forEach((i,k)=> flyCoin(cells[i], k*95));
  setMeterUI();
  await zzz(idx.length*95*TF + 620);
}
async function animateEruption(){
  const vm=$('vmeter'), sc=$('scene'), fl=$('erupt-flash');
  if(vm) vm.classList.remove('hot');
  setSpriteState('bonus', 2000);                                                            // SWOGE en mode bonus
  if(sc){ sc.classList.remove('shake'); void sc.offsetWidth; sc.classList.add('shake'); }   // secousse écran
  if(fl){ fl.classList.remove('on'); void fl.offsetWidth; fl.classList.add('on'); }          // flash rouge
  try{ sndBonus(); }catch(e){} playShowerMp3();
  await zzz(1550);
  if(sc) sc.classList.remove('shake');
  if(fl) fl.classList.remove('on');
  setMeterUI();
}
setMeterUI();

/* ===================== JEU (démo, sans wallet) ===================== */
let busy=false, auto=false, turbo=false, TF=1;
function zzz(ms){ return sleep(ms*TF); }
async function doSpin(){
  if (busy) return; busy=true; $('spin-btn').disabled=true;
  try {
    if (authed) {
      // ===== VRAI ARGENT : le serveur calcule le spin (provably fair) et débite/crédite le solde =====
      let r;
      try { r = await serverSpin(BET); }
      catch(e){ if(e&&e.needDeposit){ gtoast('Solde insuffisant — dépose du $SWOGE'); openPanel('dep'); } busy=false; $('spin-btn').disabled=false; return; }
      const s = r.outcome;
      await animateSpin(s);
      if (s.erupt){ collectMeter=COLLECT_CAP; await collectSwoge(s.grid); await animateEruption(); collectMeter=s.meter; setMeterUI(); }
      else { collectMeter=s.meter; await collectSwoge(s.grid); }
      if (s.bonus) await animateBonus(s.bonus);
      if (s.erupt) await animateBonus(s.erupt);
      setBalance(r.balance);
    } else {
      // ===== DÉMO (non connecté) : calcul local, ne touche aucun solde =====
      const s = computeSpin();
      await animateSpin(s);
      const sw = s.grid.filter(x=>x==='SWOGE').length; collectMeter += sw;
      let erupt=null; if (collectMeter>=COLLECT_CAP){ collectMeter-=COLLECT_CAP; erupt=runBonus(3); }
      await collectSwoge(s.grid);
      if (s.bonus) await animateBonus(s.bonus);
      if (erupt){ await animateEruption(); await animateBonus(erupt); }
    }
  } catch(e){}
  busy=false; $('spin-btn').disabled=false;
  if (auto) setTimeout(()=>{ if(auto && !busy) doSpin(); }, 400);
}
async function forceBonus(){
  if (busy) return; busy=true; $('spin-btn').disabled=true;
  try {
    if (authed) {
      let r;
      try { r = await serverBuyBonus(BET); }
      catch(e){ if(e&&e.needDeposit){ gtoast('Solde insuffisant pour acheter le bonus'); openPanel('dep'); } busy=false; $('spin-btn').disabled=false; return; }
      await animateBonus(r.outcome.bonus); setBalance(r.balance);
    } else {
      const b = runBonus(3); await animateBonus(b);
    }
  } catch(e){}
  busy=false; $('spin-btn').disabled=false;
  if (auto) setTimeout(()=>{ if(auto && !busy) doSpin(); }, 400);
}
