let SERVER_URL = "wss://web-production-220a3.up.railway.app";
(function(){ var q=new URLSearchParams(location.search).get("server"); if(q) SERVER_URL=q; })();
const CHAIN={ id:4663, hex:"0x1237", name:"Robinhood Chain", rpc:"https://rpc.mainnet.chain.robinhood.com", scan:"https://robinhoodchain.blockscout.com", sym:"ETH" };
let TOKEN="0x8a166Fb41Cd659a0a43396272FF73973Ce29F817", VAULT="", MIN_WITHDRAW="50";
const ERC20_ABI=["function approve(address,uint256) returns (bool)","function allowance(address,address) view returns (uint256)","function balanceOf(address) view returns (uint256)"];
const VAULT_ABI=["function deposit(uint256)","function withdraw(uint256 cumulative,uint256 deadline,uint8 v,bytes32 r,bytes32 s)"];
let provider=null, signer=null, ws=null, authed=false, myAddr=null, loginNonce=null, balance=0, walletSwoge=0, pendingVolcano=null;
/* Telegram user id — needed so the Adsgram reward postback can find this account */
var TG_ID=null; try{ var _tg=window.Telegram&&window.Telegram.WebApp; if(_tg&&_tg.initDataUnsafe&&_tg.initDataUnsafe.user) TG_ID=_tg.initDataUnsafe.user.id; }catch(e){}

function gtoast(t){ var e=$('g-toast'); e.textContent=t; e.classList.add('show'); clearTimeout(e._t); e._t=setTimeout(()=>e.classList.remove('show'),2400); }
function fmtBig(n){ n=parseFloat(n||0); if(n>=1e9)return (n/1e9).toFixed(2)+"B"; if(n>=1e6)return (n/1e6).toFixed(2)+"M"; if(n>=1e3)return (n/1e3).toFixed(2)+"K"; return (Math.round(n*100)/100).toString(); }
function setDot(on){ $('dot').className='statusdot'+(on?' on':''); }
function setBalance(b){ balance=parseFloat(b||0); $('bal').textContent=fmtBig(balance); }
function send(o){ if(ws&&ws.readyState===1) ws.send(JSON.stringify(o)); }
function esc(s){ return String(s==null?'':s).replace(/[<>&]/g,function(c){return{'<':'&lt;','>':'&gt;','&':'&amp;'}[c];}); }

function serverSpin(bet){ return new Promise((res,rej)=>{ if(!(ws&&ws.readyState===1)) return rej(new Error('offline'));
  pendingVolcano={res,rej}; send({type:'volcanoSpin',bet}); setTimeout(()=>{ if(pendingVolcano){ var p=pendingVolcano; pendingVolcano=null; p.rej(new Error('timeout')); } },9000); }); }
function serverBuyBonus(bet){ return new Promise((res,rej)=>{ if(!(ws&&ws.readyState===1)) return rej(new Error('offline'));
  pendingVolcano={res,rej}; send({type:'volcanoBuyBonus',bet}); setTimeout(()=>{ if(pendingVolcano){ var p=pendingVolcano; pendingVolcano=null; p.rej(new Error('timeout')); } },12000); }); }

function connect(){
  try{ ws=new WebSocket(SERVER_URL); }catch(e){ setDot(false); return; }
  ws.onopen=function(){ setDot(true); if(myAddr) doLogin(); };
  ws.onclose=function(){ setDot(false); authed=false; setTimeout(connect,3000); };
  ws.onerror=function(){ setDot(false); };
  ws.onmessage=function(ev){ var m; try{ m=JSON.parse(ev.data); }catch(e){ return; }
    if(m.type==='state') return;
    if(m.type==='hello'){ loginNonce=m.loginNonce; if(m.vault)VAULT=m.vault; if(m.token)TOKEN=m.token; if(m.minWithdraw)MIN_WITHDRAW=m.minWithdraw; }
    else if(m.type==='auth'){ authed=true; myAddr=m.address; onAuthed(); setBalance(m.balance); if(m.stake) setStakeInfo(m.stake); if(m.quests) renderQuests(m.quests); if(m.bonus) renderBonus(m.bonus); if(m.welcomeGranted>0) gtoast('🎁 Welcome! +'+m.welcomeGranted+' $SWOGE to try'); if(m.volcano&&m.volcano.meter!=null){ collectMeter=m.volcano.meter; setMeterUI(); } }
    else if(m.type==='balance'||m.type==='deposit'){ setBalance(m.balance); if(m.type==='deposit') gtoast('💰 Deposit credited'); }
    else if(m.type==='volcanoResult'){ if(pendingVolcano){ var pv=pendingVolcano; pendingVolcano=null; pv.res(m); } }
    else if(m.type==='need_deposit'){ setBalance(m.balance); if(pendingVolcano){ var p2=pendingVolcano; pendingVolcano=null; p2.rej({needDeposit:true}); } }
    else if(m.type==='error'){ if(pendingVolcano){ var p3=pendingVolcano; pendingVolcano=null; p3.rej(new Error(m.error||'error')); } gtoast(m.error||'error'); }
    else if(m.type==='voucher'){ setBalance(m.balance); submitWithdraw(m.voucher); }
    else if(m.type==='stakeInfo'){ setStakeInfo(m); }
    else if(m.type==='stakeUnstaked'){ setStakeInfo(m); gtoast('Unstaked '+fmtBig(m.returned)+' $SWOGE'); }
    else if(m.type==='stakeClaimed'){ gtoast('🌾 Claimed '+m.reward+' $SWOGE'); }
    else if(m.type==='quests'){ renderQuests(m.quests); }
    else if(m.type==='questClaimed'){ setBalance(m.balance); renderQuests(m.quests); gtoast('🎯 Quest +'+m.reward+' $SWOGE!'); }
    else if(m.type==='bonus'){ renderBonus(m.bonus); }
    else if(m.type==='welcomeClaimed'){ setBalance(m.balance); renderBonus(m.bonus); gtoast('🎁 +'+m.reward+' $SWOGE!'); }
    else if(m.type==='streakClaimed'){ setBalance(m.balance); renderBonus(m.bonus); gtoast('🔥 Day '+m.day+' : +'+m.reward+' $SWOGE!'); }
    else if(m.type==='adReward'){ setBalance(m.balance); if(m.bonus) renderBonus(m.bonus); gtoast('📺 +'+m.reward+' $SWOGE !'); }
  };
}
function onAuthed(){ $('connectBtn').style.display='none'; $('emailBtn').style.display='none'; $('menuBtn').style.display=''; }

async function doConnect(){
  var eth=window.ethereum;
  if(!eth){ gtoast('No wallet found — use email sign-in'); openEmailLogin(); return; }
  try{
    await eth.request({method:'eth_requestAccounts'});
    var cid=await eth.request({method:'eth_chainId'});
    if(cid!==CHAIN.hex){ try{ await eth.request({method:'wallet_switchEthereumChain',params:[{chainId:CHAIN.hex}]}); }
      catch(sw){ if(sw&&sw.code===4902){ await eth.request({method:'wallet_addEthereumChain',params:[{chainId:CHAIN.hex,chainName:CHAIN.name,nativeCurrency:{name:'Ether',symbol:CHAIN.sym,decimals:18},rpcUrls:[CHAIN.rpc],blockExplorerUrls:[CHAIN.scan]}]}); } } }
    await onWalletReady(eth); try{ localStorage.setItem('swogeAuth','wallet'); }catch(e){}
  }catch(e){ gtoast(String(e.message||e).slice(0,90)); }
}
async function onWalletReady(eth, addr){ provider=new ethers.providers.Web3Provider(eth,'any'); signer=provider.getSigner(); myAddr=(addr||(await signer.getAddress())).toLowerCase(); if(ws&&ws.readyState===1) doLogin(); else connect(); }
async function doLogin(){ if(!signer||loginNonce==null) return; try{ var msg='SWOGE Pusher login\nnonce: '+loginNonce; var sig=await signer.signMessage(msg); send({type:'login',message:msg,signature:sig,name:myAddr.slice(0,6),tgId:TG_ID}); }catch(e){ gtoast('login cancelled'); } }
var PRIVY_APP_ID='cmsga0yzp00a50biaf9vlzzd2', privyLoaded=false, privyEmail='';
function loadPrivy(){ return new Promise(function(res,rej){ if(privyLoaded) return res();
  var s=document.createElement('script'); s.src='privy-swoge.js'; s.onload=function(){ privyLoaded=true; try{ SwogePrivy.init(PRIVY_APP_ID); }catch(e){} res(); }; s.onerror=function(){ rej(new Error('load failed')); }; document.head.appendChild(s); }); }
async function openEmailLogin(){ try{ await loadPrivy(); }catch(e){ gtoast("Couldn't load email login"); return; } $('emCodeWrap').style.display='none'; $('emCode').value=''; $('emMsg').textContent='A wallet is created for you automatically — no app needed.'; showBox('email'); }

var stStaked=0,stPending=0,stAprBps=10000,stSyncMs=0,stLocked=0,stUnlocked=0,stNextUnlock=null,stPenaltyBps=5000,stLockDays=365;
function setStakeInfo(m){ if(m.staked!=null)stStaked=parseFloat(m.staked); if(m.pending!=null)stPending=parseFloat(m.pending); if(m.aprBps!=null)stAprBps=m.aprBps;
  if(m.locked!=null)stLocked=parseFloat(m.locked); if(m.unlocked!=null)stUnlocked=parseFloat(m.unlocked); if(m.penaltyBps!=null)stPenaltyBps=m.penaltyBps; if(m.lockDays!=null)stLockDays=m.lockDays; if('nextUnlock' in m)stNextUnlock=m.nextUnlock; if(m.balance!=null)setBalance(m.balance);
  stSyncMs=Date.now(); var ap=$('stApr'); if(ap) ap.textContent=(stAprBps/100)+'% APR · locked '+stLockDays+' days · yield every second'; renderStake(); }
function livePending(){ var el=(Date.now()-stSyncMs)/1000; return stPending+stStaked*(stAprBps/10000)*(el/31536000); }
function fmtYield(n){ n=parseFloat(n||0); return n>=1000?fmtBig(n):n.toFixed(4); }
function renderStake(){ if(!$('stStaked'))return; $('stStaked').textContent=fmtBig(stStaked); $('stPending').textContent=fmtYield(livePending()); $('stUnlocked').textContent=fmtBig(stUnlocked);
  var el=$('stLock'); if(stLocked>0){ var w=stNextUnlock?new Date(stNextUnlock).toLocaleDateString():'—'; el.innerHTML='🔒 '+fmtBig(stLocked)+' locked until '+w+' — early unstake forfeits '+(stPenaltyBps/100)+'%.'; el.style.color='#ff6b6b'; } else if(stStaked>0){ el.textContent='✅ All unlocked — no penalty.'; el.style.color='#7CFF9B'; } else el.textContent=''; }
setInterval(function(){ if($('ovl').classList.contains('show')&&$('box-stake').classList.contains('show')) $('stPending').textContent=fmtYield(livePending()); },250);
function doStake(){ var v=($('stAmt').value||'').replace(',','.').trim(); if(!(parseFloat(v)>0))return gtoast('enter an amount'); if(!confirm('Stake '+v+' $SWOGE at '+(stAprBps/100)+'% APR?\nLocks '+stLockDays+' days.'))return; send({type:'stake',amount:v}); $('stAmt').value=''; }
function doUnstake(){ if(!(stStaked>0))return gtoast('nothing staked'); if(stLocked>0&&!confirm('⚠️ '+fmtBig(stLocked)+' still locked. Lose '+(stPenaltyBps/100)+'%?'))return; send({type:'unstake'}); }
function doClaim(){ send({type:'claimStake'}); }

function renderQuests(list){ var box=$('questrows'); if(!box||!list) return; var h=[];
  list.forEach(function(q){
    var goal=(q.target!=null?q.target:(q.goal!=null?q.goal:0)), prog=q.progress||0;
    var done=(q.done!=null?q.done:(goal>0?prog>=goal:true));
    var claimable=(q.claimable!=null?q.claimable:(done&&!q.claimed&&!q.locked));
    var pct=goal>0?Math.min(100,Math.round(100*prog/goal)):(done?100:0);
    var st=q.claimed?'done':(claimable?'on':'off');
    var label=q.claimed?'✓ Claimed':(claimable?'Claim +'+q.reward:(q.locked?'🔒 Deposit to unlock':(goal>0?prog+' / '+goal:'Play to unlock')));
    h.push('<div class="quest"><div class="qh"><span>'+esc(q.label||q.id)+'</span></div><div class="qbar"><i style="width:'+(pct*0.85).toFixed(1)+'%"></i></div><button class="qclaim '+st+'" data-q="'+esc(q.id)+'" '+(st==='on'?'':'disabled')+'>'+label+'</button></div>'); });
  box.innerHTML=h.join(''); box.querySelectorAll('.qclaim.on').forEach(function(b){ b.addEventListener('click',function(){ send({type:'claimQuest',id:b.getAttribute('data-q')}); }); }); }

/* ---- Welcome bonus + 7-day streak + rewarded video (Adsgram) ---- */
var bonusData=null, AdController=null;
/* bascule un bouton entre image (texte gravé) et bouton texte CSS */
var IMG_CLASSES=['wimg','pimg','cimg','claim1','claim2','claim3','claim5','claim7','claim10','claim15'];
var CLAIM_AMTS=[1,2,3,5,7,10,15];   // montants pour lesquels on a une image CLAIM +N
function setBtnImg(el, cls){ if(!el) return; IMG_CLASSES.forEach(function(c){ el.classList.remove(c); }); if(cls){ el.classList.add('imgbtn', cls); } else { el.classList.remove('imgbtn'); } }
function claimCls(amt){ return CLAIM_AMTS.indexOf(amt)>=0 ? 'claim'+amt : null; }   // image si dispo, sinon bouton texte
function initAdsgram(blockId){ try{ if(window.Adsgram&&!AdController&&blockId){ AdController=window.Adsgram.init({ blockId:String(blockId) }); } }catch(e){} }
function watchAd(){
  if(!TG_ID){ gtoast('Open the game inside Telegram to watch ads'); return; }
  if(!AdController){ // SDK may still be loading — try once more
    if(bonusData&&bonusData.ad&&bonusData.ad.blockId) initAdsgram(bonusData.ad.blockId);
    if(!AdController){ gtoast('Ad not ready yet — try again'); return; }
  }
  var b=$('adWatch'); if(b){ b.disabled=true; b.textContent='Loading ad…'; }
  AdController.show().then(function(){ gtoast('✅ Ad finished — reward incoming'); })
    .catch(function(){ gtoast('Ad skipped or unavailable'); })
    .finally(function(){ send({type:'bonusState'}); });
}
function renderBonus(b){ if(!b) return; bonusData=b;
  // rewarded video
  if(b.ad){ var ar=$('adReward'); if(ar) ar.textContent='+'+b.ad.reward;
    var an=$('adNote'), aw=$('adWatch');
    if(b.ad.left<=0){ if(an) an.textContent='Daily limit reached ('+b.ad.dailyCap+'/'+b.ad.dailyCap+'). Come back tomorrow!'; if(aw){ setBtnImg(aw,null); aw.disabled=true; aw.textContent='Back tomorrow'; } }
    else if(b.ad.cooldown>0){ if(aw){ setBtnImg(aw,null); aw.disabled=true; aw.textContent='Wait '+b.ad.cooldown+'s'; } if(an) an.textContent=b.ad.left+' ad(s) left today.'; }
    else { if(aw){ setBtnImg(aw,'wimg'); aw.disabled=false; aw.textContent='📺 Watch an ad (+'+b.ad.reward+')'; } if(an) an.textContent=b.ad.left+' ad(s) left today.'; }
    if(b.ad.blockId) initAdsgram(b.ad.blockId);
  }
  // welcome bonus
  if(b.welcome){ var wc=$('welcomeCard');
    if(b.welcome.claimed){ if(wc) wc.style.display='none'; }
    else if(wc){ wc.style.display='';
      var wr=$('wcReward'); if(wr) wr.textContent='+'+b.welcome.reward;
      var wb=$('wcClaim'), wn=$('wcNote');
      if(b.welcome.claimable){ setBtnImg(wb,claimCls(b.welcome.reward)); wb.disabled=false; wb.textContent='Claim +'+b.welcome.reward; if(wn) wn.textContent='Nice! Grab your reward.'; }
      else { setBtnImg(wb,'pimg'); wb.disabled=true; wb.textContent='Play your bonus'; if(wn) wn.textContent='You got '+b.welcome.amount+' $SWOGE — play them to unlock +'+b.welcome.reward+'.'; }
    }
  }
  // 7-day streak
  if(b.streak){ var row=$('streakDays');
    if(row){ var rw=b.streak.rewards||[], hh='';
      for(var i=0;i<rw.length;i++){ var dn=i+1, cls='sday';
        if(b.streak.claimedToday){ if(dn<=b.streak.day) cls+=' done'; }
        else { if(dn<b.streak.day) cls+=' done'; else if(dn===b.streak.day) cls+=' today'; }
        hh+='<div class="'+cls+' day'+dn+'"></div>';
      }
      row.innerHTML=hh;
    }
    var sb=$('stkClaim');
    if(sb){ if(b.streak.claimable){ setBtnImg(sb,claimCls(b.streak.todayReward)); sb.disabled=false; sb.textContent='Claim day '+b.streak.day+' (+'+b.streak.todayReward+')'; }
      else { setBtnImg(sb,'cimg'); sb.disabled=true; sb.textContent='✓ Claimed today'; } }
  }
}

async function loadWalletBalances(){ if(!provider||!myAddr) return; var e='—', sw='—';
  try{ var b=await provider.getBalance(myAddr); e=(+ethers.utils.formatEther(b)).toFixed(5); }catch(x){}
  try{ var t=new ethers.Contract(TOKEN,ERC20_ABI,provider), bb=await t.balanceOf(myAddr); walletSwoge=+ethers.utils.formatUnits(bb,18); sw=fmtBig(walletSwoge); }catch(x){}
  ['acEth','depEth'].forEach(function(id){ var el=$(id); if(el) el.textContent=e; }); ['acSwoge','depSwoge'].forEach(function(id){ var el=$(id); if(el) el.textContent=sw; }); }
async function doDeposit(){ if(!signer)return gtoast('connect a wallet'); if(!VAULT)return gtoast('server has no vault set');
  var s=($('depAmt').value||'').replace(',','.').trim(), amt; try{ amt=ethers.utils.parseUnits(s,18); }catch(e){ return gtoast('bad amount'); } if(amt.lte(0))return gtoast('enter an amount');
  try{ var token=new ethers.Contract(TOKEN,ERC20_ABI,signer), vault=new ethers.Contract(VAULT,VAULT_ABI,signer); var allow=await token.allowance(myAddr,VAULT);
    if(allow.lt(amt)){ gtoast('approve $SWOGE…'); var ta=await token.approve(VAULT,ethers.constants.MaxUint256); await ta.wait(); }
    gtoast('depositing…'); var tx=await vault.deposit(amt); await tx.wait(); gtoast('✅ deposited'); $('depAmt').value=''; loadWalletBalances(); }catch(e){ gtoast('deposit: '+String(e.reason||e.message||e).slice(0,70)); } }
function requestWithdraw(){ var s=($('wdAmt').value||'').replace(',','.').trim(); if(!s||parseFloat(s)<parseFloat(MIN_WITHDRAW))return gtoast('min '+MIN_WITHDRAW+' $SWOGE'); send({type:'withdraw',amount:s}); gtoast('requesting voucher…'); }
async function submitWithdraw(v){ if(!signer)return; try{ var vault=new ethers.Contract(v.vault||VAULT,VAULT_ABI,signer); gtoast('confirm withdrawal…'); var tx=await vault.withdraw(v.cumulative,v.deadline,v.v,v.r,v.s); await tx.wait(); gtoast('✅ paid out'); closePanel(); }catch(e){ gtoast('withdraw: '+String(e.reason||e.message||e).slice(0,70)); } }
function openAccount(){ if(!myAddr)return gtoast('connect first'); $('acAddr').value=myAddr; $('acExplorer').href=CHAIN.scan+'/address/'+myAddr; $('acSwoge').textContent='…'; $('acEth').textContent='…'; loadWalletBalances(); }

var PANELS=['dep','wd','wallet','stake','quests','email'];
function showBox(name){ $('ovl').classList.add('show'); PANELS.forEach(function(b){ var el=$('box-'+b); if(el) el.classList.toggle('show', b===name); }); }
function closePanel(){ $('ovl').classList.remove('show'); PANELS.forEach(function(b){ var el=$('box-'+b); if(el) el.classList.remove('show'); }); }
